using System.ComponentModel;
using System.Net;
using System.Text;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddHttpClient();

builder.Services.AddChatClient(chatBuilder => chatBuilder
    .UseOpenAIChatClient(
        builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18"));

builder.Services.AddSingleton<ResearchTools>();

builder.Services.AddSingleton(sp =>
{
    var chatClient = sp.GetRequiredService<IChatClient>();
    var tools = sp.GetRequiredService<ResearchTools>();

    var agent = new ChatClientAgent(
        chatClient,
        name: "ResearchAgent",
        description: "An AI agent that researches topics by searching the web and taking notes.",
        instructions: """
            You are a research assistant. When given a topic, you must:
            1. Search the web for information about the topic using the search_web tool (perform 2-3 searches with different queries).
            2. Take notes on key findings using the save_note tool.
            3. After gathering enough information, provide a comprehensive summary of your findings.

            Always search before summarizing. Take notes on the most important facts you discover.
            When you're done researching, present a clear, organized summary.
            """,
        tools:
        [
            AIFunctionFactory.Create(tools.SearchWebAsync),
            AIFunctionFactory.Create(tools.SaveNote),
            AIFunctionFactory.Create(tools.GetNotes),
        ]);

    agent.ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
    };

    return agent;
});

builder.Services.AddHostedService<ResearchWorker>();

builder.Logging.SetMinimumLevel(LogLevel.Warning);

var app = builder.Build();
await app.RunAsync();

/// <summary>
/// Background service that prompts the user for topics and runs the research agent.
/// </summary>
sealed class ResearchWorker(
    ChatClientAgent agent,
    IHostApplicationLifetime lifetime,
    ILogger<ResearchWorker> logger) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        Console.WriteLine("╔══════════════════════════════════════╗");
        Console.WriteLine("║       AI Research Agent              ║");
        Console.WriteLine("║  Type a topic to research, or       ║");
        Console.WriteLine("║  'quit' to exit.                    ║");
        Console.WriteLine("╚══════════════════════════════════════╝");
        Console.WriteLine();

        while (!stoppingToken.IsCancellationRequested)
        {
            Console.Write("Research topic> ");
            var topic = Console.ReadLine();

            if (string.IsNullOrWhiteSpace(topic))
                continue;

            if (topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
            {
                lifetime.StopApplication();
                return;
            }

            try
            {
                Console.WriteLine($"\n🔍 Researching: {topic}\n");

                var session = await agent.CreateSessionAsync(cancellationToken: stoppingToken);

                await foreach (var update in agent.RunStreamingAsync(
                    topic, session, cancellationToken: stoppingToken))
                {
                    foreach (var content in update.Contents)
                    {
                        if (content is TextContent text)
                        {
                            Console.Write(text.Text);
                        }
                        else if (content is FunctionCallContent fc)
                        {
                            Console.ForegroundColor = ConsoleColor.DarkGray;
                            Console.Write($"\n  ⚙ Calling {fc.Name}...");
                            Console.ResetColor();
                        }
                        else if (content is FunctionResultContent fr)
                        {
                            Console.ForegroundColor = ConsoleColor.DarkGray;
                            var preview = fr.Result?.ToString()?[..Math.Min(80, fr.Result.ToString()!.Length)] ?? "";
                            Console.Write($" done ({preview}...)");
                            Console.ResetColor();
                        }
                    }
                }

                Console.WriteLine("\n");
            }
            catch (Exception ex)
            {
                logger.LogError(ex, "Research failed for topic: {Topic}", topic);
                Console.ForegroundColor = ConsoleColor.Red;
                Console.WriteLine($"\n❌ Research failed: {ex.Message}\n");
                Console.ResetColor();
            }
        }
    }
}

/// <summary>
/// Tools available to the research agent for web search and note-taking.
/// </summary>
sealed class ResearchTools(IHttpClientFactory httpClientFactory)
{
    private readonly List<string> _notes = [];

    [Description("Search the web for information about a query. Returns a list of search result snippets.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query to look up")] string query,
        CancellationToken cancellationToken = default)
    {
        var client = httpClientFactory.CreateClient();
        client.DefaultRequestHeaders.UserAgent.ParseAdd(
            "Mozilla/5.0 (compatible; ResearchAgent/1.0)");

        var encoded = WebUtility.UrlEncode(query);
        var url = $"https://lite.duckduckgo.com/lite/?q={encoded}";

        try
        {
            var html = await client.GetStringAsync(url, cancellationToken);

            // Extract text snippets from the lite HTML results
            var results = ParseDuckDuckGoLite(html);

            if (results.Count == 0)
                return $"No results found for '{query}'.";

            var sb = new StringBuilder();
            sb.AppendLine($"Search results for '{query}':");
            for (int i = 0; i < Math.Min(results.Count, 5); i++)
            {
                sb.AppendLine($"\n[{i + 1}] {results[i]}");
            }

            return sb.ToString();
        }
        catch (HttpRequestException ex)
        {
            return $"Search failed for '{query}': {ex.Message}";
        }
    }

    [Description("Save a research note for later reference. Use this to record important findings.")]
    public string SaveNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        return $"Note saved ({_notes.Count} total notes).";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        sb.AppendLine($"Saved notes ({_notes.Count}):");
        for (int i = 0; i < _notes.Count; i++)
        {
            sb.AppendLine($"\n[{i + 1}] {_notes[i]}");
        }

        return sb.ToString();
    }

    private static List<string> ParseDuckDuckGoLite(string html)
    {
        var results = new List<string>();

        // Extract text between <td> tags that contain result snippets
        var spans = html.Split("<td", StringSplitOptions.RemoveEmptyEntries);
        foreach (var span in spans)
        {
            if (!span.Contains("result-snippet", StringComparison.OrdinalIgnoreCase))
                continue;

            var text = StripHtmlTags(span);
            text = WebUtility.HtmlDecode(text.Trim());

            if (text.Length > 30)
            {
                results.Add(text);
            }
        }

        // Fallback: extract any substantial text blocks
        if (results.Count == 0)
        {
            var blocks = html.Split("<a", StringSplitOptions.RemoveEmptyEntries);
            foreach (var block in blocks)
            {
                if (!block.Contains("rel=\"nofollow\"", StringComparison.OrdinalIgnoreCase))
                    continue;

                var text = StripHtmlTags(block);
                text = WebUtility.HtmlDecode(text.Trim());

                if (text.Length > 20 && !text.StartsWith("http", StringComparison.OrdinalIgnoreCase))
                {
                    results.Add(text);
                }
            }
        }

        return results;
    }

    private static string StripHtmlTags(string html)
    {
        var sb = new StringBuilder();
        bool inTag = false;
        foreach (char c in html)
        {
            if (c == '<') { inTag = true; continue; }
            if (c == '>') { inTag = false; continue; }
            if (!inTag) sb.Append(c);
        }

        return sb.ToString();
    }
}

