+/// <summary>
+/// Background service that prompts the user for topics and runs the research agent.
+/// </summary>
+sealed class ResearchWorker(
+    ChatClientAgent agent,
+    IHostApplicationLifetime lifetime,
+    ILogger<ResearchWorker> logger) : BackgroundService
+{
+    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
+    {
+        Console.WriteLine("╔══════════════════════════════════════╗");
+        Console.WriteLine("║       AI Research Agent              ║");
+        Console.WriteLine("║  Type a topic to research, or       ║");
+        Console.WriteLine("║  'quit' to exit.                    ║");
+        Console.WriteLine("╚══════════════════════════════════════╝");
+        Console.WriteLine();
+
+        while (!stoppingToken.IsCancellationRequested)
+        {
+            Console.Write("Research topic> ");
+            var topic = Console.ReadLine();
+
+            if (string.IsNullOrWhiteSpace(topic))
+                continue;
+
+            if (topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
+            {
+                lifetime.StopApplication();
+                return;
+            }
+
+            try
+            {
+                Console.WriteLine($"\n🔍 Researching: {topic}\n");
+
+                var session = await agent.CreateSessionAsync(cancellationToken: stoppingToken);
+
+                await foreach (var update in agent.RunStreamingAsync(
+                    topic, session, cancellationToken: stoppingToken))
+                {
+                    foreach (var content in update.Contents)
+                    {
+                        if (content is TextContent text)
+                        {
+                            Console.Write(text.Text);
+                        }
+                        else if (content is FunctionCallContent fc)
+                        {
+                            Console.ForegroundColor = ConsoleColor.DarkGray;
+                            Console.Write($"\n  ⚙ Calling {fc.Name}...");
+                            Console.ResetColor();
+                        }
+                        else if (content is FunctionResultContent fr)
+                        {
+                            Console.ForegroundColor = ConsoleColor.DarkGray;
+                            var preview = fr.Result?.ToString()?[..Math.Min(80, fr.Result.ToString()!.Length)] ?? "";
+                            Console.Write($" done ({preview}...)");
+                            Console.ResetColor();
+                        }
+                    }
+                }
+
+                Console.WriteLine("\n");
+            }
+            catch (Exception ex)
+            {
+                logger.LogError(ex, "Research failed for topic: {Topic}", topic);
+                Console.ForegroundColor = ConsoleColor.Red;
+                Console.WriteLine($"\n❌ Research failed: {ex.Message}\n");
+                Console.ResetColor();
+            }
+        }
+    }
+}
