+/// <summary>
+/// Tools available to the research agent for web search and note-taking.
+/// </summary>
+sealed class ResearchTools(IHttpClientFactory httpClientFactory)
+{
+    private readonly List<string> _notes = [];
+
+    [Description("Search the web for information about a query. Returns a list of search result snippets.")]
+    public async Task<string> SearchWebAsync(
+        [Description("The search query to look up")] string query,
+        CancellationToken cancellationToken = default)
+    {
+        var client = httpClientFactory.CreateClient();
+        client.DefaultRequestHeaders.UserAgent.ParseAdd(
+            "Mozilla/5.0 (compatible; ResearchAgent/1.0)");
+
+        var encoded = WebUtility.UrlEncode(query);
+        var url = $"https://lite.duckduckgo.com/lite/?q={encoded}";
+
+        try
+        {
+            var html = await client.GetStringAsync(url, cancellationToken);
+
+            // Extract text snippets from the lite HTML results
+            var results = ParseDuckDuckGoLite(html);
+
+            if (results.Count == 0)
+                return $"No results found for '{query}'.";
+
+            var sb = new StringBuilder();
+            sb.AppendLine($"Search results for '{query}':");
+            for (int i = 0; i < Math.Min(results.Count, 5); i++)
+            {
+                sb.AppendLine($"\n[{i + 1}] {results[i]}");
+            }
+
+            return sb.ToString();
+        }
+        catch (HttpRequestException ex)
+        {
+            return $"Search failed for '{query}': {ex.Message}";
+        }
+    }
+
+    [Description("Save a research note for later reference. Use this to record important findings.")]
+    public string SaveNote(
+        [Description("The note content to save")] string note)
+    {
+        _notes.Add(note);
+        return $"Note saved ({_notes.Count} total notes).";
+    }
+
+    [Description("Retrieve all saved research notes.")]
+    public string GetNotes()
+    {
+        if (_notes.Count == 0)
+            return "No notes saved yet.";
+
+        var sb = new StringBuilder();
+        sb.AppendLine($"Saved notes ({_notes.Count}):");
+        for (int i = 0; i < _notes.Count; i++)
+        {
+            sb.AppendLine($"\n[{i + 1}] {_notes[i]}");
+        }
+
+        return sb.ToString();
+    }
+
+    private static List<string> ParseDuckDuckGoLite(string html)
+    {
+        var results = new List<string>();
+
+        // Extract text between <td> tags that contain result snippets
+        var spans = html.Split("<td", StringSplitOptions.RemoveEmptyEntries);
+        foreach (var span in spans)
+        {
+            if (!span.Contains("result-snippet", StringComparison.OrdinalIgnoreCase))
+                continue;
+
+            var text = StripHtmlTags(span);
+            text = WebUtility.HtmlDecode(text.Trim());
+
+            if (text.Length > 30)
+            {
+                results.Add(text);
+            }
+        }
+
+        // Fallback: extract any substantial text blocks
+        if (results.Count == 0)
+        {
+            var blocks = html.Split("<a", StringSplitOptions.RemoveEmptyEntries);
+            foreach (var block in blocks)
+            {
+                if (!block.Contains("rel=\"nofollow\"", StringComparison.OrdinalIgnoreCase))
+                    continue;
+
+                var text = StripHtmlTags(block);
+                text = WebUtility.HtmlDecode(text.Trim());
+
+                if (text.Length > 20 && !text.StartsWith("http", StringComparison.OrdinalIgnoreCase))
+                {
+                    results.Add(text);
+                }
+            }
+        }
+
+        return results;
+    }
+
+    private static string StripHtmlTags(string html)
+    {
+        var sb = new StringBuilder();
+        bool inTag = false;
+        foreach (char c in html)
+        {
+            if (c == '<') { inTag = true; continue; }
+            if (c == '>') { inTag = false; continue; }
+            if (!inTag) sb.Append(c);
+        }
+
+        return sb.ToString();
+    }
